56	/**
57	 * A customer as they stand at one point in a scenario: who they are, plus what
58	 * they have already been quoted. `quotesSoFar` counts *quotes priced*, not
59	 * steps taken — once claim steps exist the two will differ, and it is the quote
60	 * count that decides whether a policy is a follow-up contract.
61	 */
62	interface CustomerStanding {
63	  readonly customer: Customer;
64	  readonly quotesSoFar: number;
65	}
66	
67	const PROCESSING_FEE = 5;
68	
69	/**
70	 * The spec keeps intermediate amounts as exact fractions and rounds only the
71	 * final amount. Binary floating point cannot do that: `100 * 1.1` is
72	 * 110.00000000000001, which rounds *up* to 111 instead of 110.
73	 *
74	 * So percentages are applied as integer rationals — multiply by the numerator
75	 * first, divide by the denominator last — and money is carried in hundredths
76	 * of a G. Both operands of every product stay integral, so no drift accrues.
77	 */
78	const SUBUNITS_PER_G = 100;
79	const toSubunits = (gold: number): number => Math.round(gold * SUBUNITS_PER_G);
80	
81	/**
82	 * A percentage held as an exact rational, so that it can be applied without
83	 * float drift: multiply by `num` first, divide by `den` last.
84	 *
85	 * Deliberately anonymous about *meaning*. Both sides of the business use
86	 * percentages, but they use them for opposite things — see `Rate` and `Share`,
87	 * which are the names the domain actually reads in.
88	 */
89	interface Fraction {
90	  num: number;
91	  den: number;
92	}
93	
94	/** The part of `subunits` that `fraction` denotes. */
95	const partOf = (subunits: number, fraction: Fraction): number =>
96	  (subunits * fraction.num) / fraction.den;
97	
98	/**
99	 * A modifier as an exact rational: the surcharge or discount *itself*, not the
100	 * multiplied total. +10 % is { num: 10, den: 100 }; a discount has a negative
101	 * numerator. Modifiers are summed onto a base, never multiplied through it.
102	 */
103	type Rate = Fraction;
104	
105	const FIRST_INSURANCE_SURCHARGE: Rate = { num: 10, den: 100 };
106	const CURSE_SURCHARGE: Rate = { num: 50, den: 100 };
107	const HIGH_ENCHANTMENT_SURCHARGE: Rate = { num: 30, den: 100 };
108	
109	const LOYALTY_DISCOUNT: Rate = { num: -20, den: 100 };
110	const FOLLOW_UP_DISCOUNT: Rate = { num: -15, den: 100 };
111	
112	/** An item is highly enchanted from this level upwards. */
113	const HIGH_ENCHANTMENT_LEVEL = 5;
114	
115	/** A customer is long-standing from this many years of business upwards. */
116	const LOYALTY_YEARS = 2;
117	
118	/** The modifier amount `rate` contributes against `subunits` — not the total. */
119	const rateAmount = (subunits: number, rate: Rate): number => partOf(subunits, rate);
120	
121	/** Premiums round up — in the MHPCO's favour. */
122	const toPremiumGold = (subunits: number): number => Math.ceil(subunits / SUBUNITS_PER_G);
123	
124	/**
125	 * What the MHPCO charges to insure an item type, and what it insures it for.
126	 * Two independent facts, held together because they are looked up together.
127	 *
128	 * Every insuranceValue here happens to be ten times its basePremium. That is a
129	 * coincidence of the current rate card, not a rule the spec states — the two
130	 * columns are given independently — so it is left unfactored. Deriving one from
131	 * the other would make a future type whose value is not 10x its premium
132	 * inexpressible.
133	 */
134	interface Rating {
135	  readonly basePremium: number;
136	  readonly insuranceValue: number;
137	  /** Components price in blocks; main items do not. */
138	  readonly isComponent: boolean;
139	}
140	
141	const RATE_CARD: Record<string, Rating> = {
142	  sword: { basePremium: 100, insuranceValue: 1000, isComponent: false },
143	  amulet: { basePremium: 60, insuranceValue: 600, isComponent: false },
144	  staff: { basePremium: 80, insuranceValue: 800, isComponent: false },
145	  potion: { basePremium: 40, insuranceValue: 400, isComponent: false },
146	  rune: { basePremium: 25, insuranceValue: 250, isComponent: true },
147	  moonstone: { basePremium: 25, insuranceValue: 250, isComponent: true },
148	};
149	
150	/**
151	 * An unrated type is worth nothing on both counts and is not a component.
152	 *
153	 * This is a placeholder, not a decision. The spec calls for rejecting unknown
154	 * item types outright; the todo test for a broomstick quote is what will turn
155	 * this into a raised error, at which point the `?? UNRATED` fallback goes away.
156	 */
157	const UNRATED: Rating = { basePremium: 0, insuranceValue: 0, isComponent: false };
158	
159	const ratingOf = (item: Item): Rating => RATE_CARD[item.type] ?? UNRATED;
160	
161	const basePremiumOf = (item: Item): number => ratingOf(item).basePremium;
162	
163	/** What an item is insured for — distinct from what it costs to insure. */
164	const insuranceValueOf = (item: Item): number => ratingOf(item).insuranceValue;
165	
166	const isComponent = (item: Item): boolean => ratingOf(item).isComponent;
167	
168	/** Exactly this many alike components form a block, priced as one unit. */
169	const COMPONENT_BLOCK_SIZE = 3;
170	const COMPONENT_BLOCK_PREMIUM = 60;
171	
172	/** Splits items into those matching the predicate and those that do not. */
173	const partition = (items: Item[], matches: (item: Item) => boolean): [Item[], Item[]] => [
174	  items.filter(matches),
175	  items.filter((item) => !matches(item)),
176	];
177	
178	const groupByType = (items: Item[]): Map<string, Item[]> => {
179	  const groups = new Map<string, Item[]>();
180	  for (const item of items) groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
181	
182	  return groups;
183	};
184	
185	const sumOfBasePremiums = (items: Item[]): number =>
186	  items.reduce((total, item) => total + basePremiumOf(item), 0);
187	
188	/**
189	 * Alike components — those of the very same type — form a block when there are
190	 * exactly COMPONENT_BLOCK_SIZE of them; the block is priced as one unit.
191	 * Any other count is priced per component.
192	 */
193	const componentGroupPremium = (group: Item[]): number =>
194	  group.length === COMPONENT_BLOCK_SIZE ? COMPONENT_BLOCK_PREMIUM : sumOfBasePremiums(group);
195	
196	/**
197	 * The policy base premium: every insured item's base premium, summed — except
198	 * that each group of alike components is priced as blocks where it can be.
199	 */
200	const policyBasePremiumOf = (items: Item[]): number => {
201	  const [components, mainItems] = partition(items, isComponent);
202	  const componentsTotal = [...groupByType(components).values()].reduce(
203	    (total, group) => total + componentGroupPremium(group),
204	    0,
205	  );
206	
207	  return sumOfBasePremiums(mainItems) + componentsTotal;
208	};
209	
210	/** The total the given rates contribute against a shared base. */
211	const sumOfRateAmounts = (base: number, rates: Rate[]): number =>
212	  rates.reduce((total, rate) => total + rateAmount(base, rate), 0);
213	
214	const isHighlyEnchanted = (item: Item): boolean =>
215	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
216	
217	/** Which item-specific modifiers an item attracts, by its own attributes. */
218	const ratesForItem = (item: Item): Rate[] => [
219	  ...(item.cursed ? [CURSE_SURCHARGE] : []),
220	  ...(isHighlyEnchanted(item) ? [HIGH_ENCHANTMENT_SURCHARGE] : []),
221	];
222	
223	const isLongStanding = (standing: CustomerStanding): boolean =>
224	  standing.customer.yearsWithMHPCO >= LOYALTY_YEARS;
225	
226	const holdsAnEarlierQuote = (standing: CustomerStanding): boolean => standing.quotesSoFar > 0;
227	
228	/** Which policy-wide modifiers a policy attracts, by the customer's standing. */
229	const ratesForPolicy = (standing: CustomerStanding): Rate[] => [
230	  FIRST_INSURANCE_SURCHARGE,
231	  ...(isLongStanding(standing) ? [LOYALTY_DISCOUNT] : []),
232	  ...(holdsAnEarlierQuote(standing) ? [FOLLOW_UP_DISCOUNT] : []),
233	];
234	
235	/** Item-specific modifiers apply to the affected item's own base premium. */
236	const sumOfItemModifierAmounts = (items: Item[]): number =>
237	  items.reduce(
238	    (total, item) =>
239	      total + sumOfRateAmounts(toSubunits(basePremiumOf(item)), ratesForItem(item)),
240	    0,
241	  );
242	
243	/**
244	 * Modifiers are additive amounts, each computed against its own base: item
245	 * modifiers against the affected item, policy-wide modifiers against the
246	 * policy base premium. The processing fee is added at the very end.
247	 */
248	const quotePremium = (items: Item[], standing: CustomerStanding): number => {
249	  const policyBase = toSubunits(policyBasePremiumOf(items));
250	
251	  return toPremiumGold(
252	    policyBase +
253	      sumOfItemModifierAmounts(items) +
254	      sumOfRateAmounts(policyBase, ratesForPolicy(standing)) +
255	      toSubunits(PROCESSING_FEE),
256	  );
257	};
258	
259	/** A deductible is withheld from each damaged item's reimbursement. */
260	const DEDUCTIBLE = 100;
261	
262	/** The MHPCO pays at most this multiple of a policy's insurance sum. */
263	const CAP_MULTIPLE = 2;
264	
265	/** Payouts round down — in the MHPCO's favour. */
266	const toPayoutGold = (subunits: number): number => Math.floor(subunits / SUBUNITS_PER_G);
267	
268	/**
269	 * A policy created by a quote step: the items it covers, and how much of its
270	 * payout cap is still available.
271	 */
272	interface Policy {
273	  readonly items: Item[];
274	  readonly remainingCap: number;
275	}
276	
277	/**
278	 * What a policy insures for in total: every covered item's own insurance value,
279	 * summed. Unmodified — curses and enchantments move the premium, not this, and
280	 * a component block is a premium discount only.
281	 */
282	const insuranceSumOf = (items: Item[]): number =>
283	  items.reduce((total, item) => total + insuranceValueOf(item), 0);
284	
285	const policyFor = (items: Item[]): Policy => ({
286	  items,
287	  remainingCap: toSubunits(insuranceSumOf(items) * CAP_MULTIPLE),
288	});
289	
290	/**
291	 * How much of a damage the MHPCO reimburses, as an exact rational. Unlike a
292	 * `Rate`, a share is the *whole* of what is paid rather than an adjustment to
293	 * it: HALF_REIMBURSEMENT is what the claimant gets, not what they lose, and
294	 * FULL_REIMBURSEMENT is the identity. Shares are multiplied through the
295	 * damage; they are never summed with one another.
296	 */
297	type Share = Fraction;
298	
299	/** The part of `subunits` that `share` reimburses. */
300	const shareAmount = (subunits: number, share: Share): number => partOf(subunits, share);
301	
302	const FULL_REIMBURSEMENT: Share = { num: 100, den: 100 };
303	const HALF_REIMBURSEMENT: Share = { num: 50, den: 100 };
304	
305	/**
306	 * Damage to an item this heavily enchanted is reimbursed at half. Note this is
307	 * a different threshold from HIGH_ENCHANTMENT_LEVEL, which governs the premium.
308	 */
309	const HALF_REIMBURSEMENT_LEVEL = 8;
310	
311	const isHeavilyEnchanted = (item: Item): boolean =>
312	  (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_LEVEL;
313	
314	/**
315	 * The share of a damage the MHPCO reimburses for an item.
316	 *
317	 * Reimbursement clauses do not stack the way premium modifiers do: exactly one
318	 * clause decides the share, and a share is multiplied through the damage rather
319	 * than summed. This is the opposite of `ratesForItem`, which collects every
320	 * modifier that applies — hence a single answer rather than a list.
321	 *
322	 * The spec also states a dragon-material clause granting *full* reimbursement,
323	 * and it is deliberately absent here. It is unobservable: full reimbursement is
324	 * already the default, and the only reducing clause (half, at enchantment >=
325	 * HALF_REIMBURSEMENT_LEVEL) is specified to win wherever both would apply. So
326	 * the dragon clause can only ever agree with this function, never override it —
327	 * no input exists for which reading `item.material` changes the answer. All
328	 * three worked dragon examples in the spec (enchantment 8 and 9 → half; 5 →
329	 * full) come out right without it.
330	 *
331	 * That makes a dragon branch unfalsifiable code: the suite stays green with it
332	 * above the enchantment check, below it, or gone. It is left out rather than
333	 * written untestable. Should a later clause make material observable — a
334	 * *reducing* dragon rule, or a full-reimbursement clause that outranks the
335	 * half — a failing test will demand it, and this note should go with it.
336	 */
337	const reimbursedShareOf = (item: Item): Share => {
338	  if (isHeavilyEnchanted(item)) return HALF_REIMBURSEMENT;
339	
340	  return FULL_REIMBURSEMENT;
341	};
342	
343	/**
344	 * What the MHPCO reimburses for one damaged item, before the cap is applied:
345	 * the reimbursed share of the damage, less the deductible.
346	 */
347	const reimbursementFor = (damage: Damage, item: Item): number =>
348	  shareAmount(toSubunits(damage.amount), reimbursedShareOf(item)) - toSubunits(DEDUCTIBLE);
349	
350	/** Everything a step may read and advance as the scenario runs. */
351	interface Ledger {
352	  readonly standing: CustomerStanding;
353	  /** Policies by the index of the quote step that created them. */
354	  readonly policies: ReadonlyMap<number, Policy>;
355	}
356	
357	/** The ledger as it stands once `policy` is on record at `stepIndex`. */
358	const withPolicy = (ledger: Ledger, stepIndex: number, policy: Policy): Ledger => ({
359	  ...ledger,
360	  policies: new Map(ledger.policies).set(stepIndex, policy),
361	});
362	
363	/**
364	 * The policy a step names, *assuming* the step names one that exists.
365	 *
366	 * No scenario yet reaches this with a dangling reference, so the assumption
367	 * holds for every case under test. It is stated here rather than asserted
368	 * silently at the call site; the todo tests for claims against absent or
369	 * mismatched policies are what will turn it into a checked failure.
370	 */
371	const assumePolicy = (ledger: Ledger, stepIndex: number): Policy => {
372	  const policy = ledger.policies.get(stepIndex);
373	  if (policy === undefined) throw new Error(`No policy created by step ${stepIndex}`);
374	
375	  return policy;
376	};
377	
378	/** A damage together with the insured item it befell. */
379	interface DamagedItem {
380	  readonly damage: Damage;
381	  readonly item: Item;
382	}
383	
384	/**
385	 * Each damage paired with the insured item it befell.
386	 *
387	 * A policy may cover several alike items — two swords, say — and each damage
388	 * entry is a separate item's misfortune. So a matched item is consumed: the
389	 * second sword damage pairs with the *other* sword, which may be enchanted
390	 * differently and so reimbursed differently.
391	 *
392	 * The pairing is returned joined rather than as an items list parallel to the
393	 * damages, so that a caller cannot read the two out of step.
394	 */
395	const pairDamagesWithItems = (policy: Policy, damages: Damage[]): DamagedItem[] => {
396	  const unharmed = [...policy.items];
397	
398	  return damages.map((damage) => {
399	    const found = unharmed.findIndex((covered) => covered.type === damage.itemType);
400	    if (found === -1) throw new Error(`Policy does not cover a ${damage.itemType}`);
401	
402	    return { damage, item: unharmed.splice(found, 1)[0] };
403	  });
404	};
405	
406	/** The result of a step, and the ledger as the *next* step will find it. */
407	interface StepOutcome {
408	  readonly result: StepResult;
409	  readonly ledger: Ledger;
410	}
411	
412	/**
413	 * A quote prices the items against the customer's standing, and leaves the
414	 * customer holding one more quote than before — which is what makes the *next*
415	 * quote a follow-up. It also creates the policy that later claims draw on.
416	 */
417	const applyQuote = (step: QuoteStep, ledger: Ledger, stepIndex: number): StepOutcome => ({
418	  result: { premium: quotePremium(step.items, ledger.standing) },
419	  ledger: withPolicy(
420	    { ...ledger, standing: { ...ledger.standing, quotesSoFar: ledger.standing.quotesSoFar + 1 } },
421	    stepIndex,
422	    policyFor(step.items),
423	  ),
424	});
425	
426	/**
427	 * What an incident's damages come to against a policy, before the cap: every
428	 * damaged item reimbursed on its own terms, each less its own deductible.
429	 */
430	const reimbursementForIncident = (incident: Incident, policy: Policy): number =>
431	  pairDamagesWithItems(policy, incident.damages).reduce(
432	    (total, { damage, item }) => total + reimbursementFor(damage, item),
433	    0,
434	  );
435	
436	/**
437	 * A claim reimburses each damaged item, less the deductible, and draws the
438	 * total down from the policy's remaining cap.
439	 *
440	 * The cap binds the payout, not merely the report: a claim worth more than the
441	 * policy has left pays out only what remains. Clamping here — in subunits,
442	 * before `toPayoutGold` rounds — is what keeps the cap from running negative
443	 * and lets it reach exactly 0 rather than a rounded near-zero.
444	 */
445	const applyClaim = (step: ClaimStep, ledger: Ledger): StepOutcome => {
446	  const policy = assumePolicy(ledger, step.policy);
447	  const payout = Math.min(
448	    reimbursementForIncident(step.incident, policy),
449	    policy.remainingCap,
450	  );
451	  const remainingCap = policy.remainingCap - payout;
452	
453	  return {
454	    result: { payout: toPayoutGold(payout), remainingCap: toPayoutGold(remainingCap) },
455	    ledger: withPolicy(ledger, step.policy, { ...policy, remainingCap }),
456	  };
457	};
458	
459	/**
460	 * Steps are processed in order, since a step's result can depend on those
461	 * before it — a quote is discounted once the customer holds an earlier one, and
462	 * a claim draws on a policy an earlier quote created.
463	 *
464	 * Each step both produces a result and hands on the ledger the next step will
465	 * see, so that a step's effect on later steps lives with the step's own logic
466	 * rather than in loose accumulators advanced by hand here.
467	 */
468	export const runScenario = (scenario: Scenario): ScenarioResults => {
469	  const results: StepResult[] = [];
470	  let ledger: Ledger = {
471	    standing: { customer: scenario.customer, quotesSoFar: 0 },
472	    policies: new Map(),
473	  };
474	
475	  scenario.steps.forEach((step, stepIndex) => {
476	    const outcome =
477	      step.op === "quote" ? applyQuote(step, ledger, stepIndex) : applyClaim(step, ledger);
478	    results.push(outcome.result);
479	    ledger = outcome.ledger;
480	  });
481	
482	  return { results };
483	};
