4	describe("MHPCO Claim Office", () => {
5	  // --- Quote: base premiums for single main items ---
6	  it("quotes an empty item list at 5 G (processing fee only)", () => {
7	    const result = runScenario({
8	      customer: { yearsWithMHPCO: 0 },
9	      steps: [{ op: "quote", items: [] }],
10	    });
11	
12	    expect(result).toEqual({ results: [{ premium: 5 }] });
13	  });
14	  it("quotes a plain sword at 115 G (100 base + 10 first insurance + 5 fee)", () => {
15	    const result = runScenario({
16	      customer: { yearsWithMHPCO: 0 },
17	      steps: [
18	        {
19	          op: "quote",
20	          items: [{ type: "sword", material: "steel", enchantment: 3, cursed: false }],
21	        },
22	      ],
23	    });
24	
25	    expect(result).toEqual({ results: [{ premium: 115 }] });
26	  });
27	  it("quotes a plain amulet at 71 G (60 base + 6 first insurance + 5 fee)", () => {
28	    const result = runScenario({
29	      customer: { yearsWithMHPCO: 0 },
30	      steps: [
31	        {
32	          op: "quote",
33	          items: [{ type: "amulet", material: "silver", enchantment: 2, cursed: false }],
34	        },
35	      ],
36	    });
37	
38	    expect(result).toEqual({ results: [{ premium: 71 }] });
39	  });
40	  it("quotes a plain staff at 93 G (80 base + 8 first insurance + 5 fee)", () => {
41	    const result = runScenario({
42	      customer: { yearsWithMHPCO: 0 },
43	      steps: [
44	        {
45	          op: "quote",
46	          items: [{ type: "staff", material: "oak", enchantment: 2, cursed: false }],
47	        },
48	      ],
49	    });
50	
51	    expect(result).toEqual({ results: [{ premium: 93 }] });
52	  });
53	  it("quotes a plain potion at 49 G (40 base + 4 first insurance + 5 fee)", () => {
54	    const result = runScenario({
55	      customer: { yearsWithMHPCO: 0 },
56	      steps: [
57	        {
58	          op: "quote",
59	          items: [{ type: "potion", material: "glass", enchantment: 1, cursed: false }],
60	        },
61	      ],
62	    });
63	
64	    expect(result).toEqual({ results: [{ premium: 49 }] });
65	  });
66	
67	  // --- Quote: components and the building block of 3 alike components ---
68	  it("prices 2 runes at 50 G base premium (no block)", () => {
69	    const result = runScenario({
70	      customer: { yearsWithMHPCO: 0 },
71	      steps: [{ op: "quote", items: [{ type: "rune" }, { type: "rune" }] }],
72	    });
73	
74	    // 50 base + 5 first insurance + 5 fee
75	    expect(result).toEqual({ results: [{ premium: 60 }] });
76	  });
77	  it("prices 3 runes at 60 G base premium (block applies)", () => {
78	    const result = runScenario({
79	      customer: { yearsWithMHPCO: 0 },
80	      steps: [{ op: "quote", items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }] }],
81	    });
82	
83	    // 60 base (block) + 6 first insurance + 5 fee
84	    expect(result).toEqual({ results: [{ premium: 71 }] });
85	  });
86	  it("prices 4 runes at 100 G base premium (no block — block requires exactly 3)", () => {
87	    const result = runScenario({
88	      customer: { yearsWithMHPCO: 0 },
89	      steps: [
90	        {
91	          op: "quote",
92	          items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }, { type: "rune" }],
93	        },
94	      ],
95	    });
96	
97	    // 100 base (no block) + 10 first insurance + 5 fee
98	    expect(result).toEqual({ results: [{ premium: 115 }] });
99	  });
100	  it("prices 7 runes at 175 G base premium (no block — block requires exactly 3)", () => {
101	    const result = runScenario({
102	      customer: { yearsWithMHPCO: 0 },
103	      steps: [{ op: "quote", items: Array.from({ length: 7 }, () => ({ type: "rune" })) }],
104	    });
105	
106	    // 175 base + 17.5 first insurance = 192.5, + 5 fee = 197.5, rounded up
107	    expect(result).toEqual({ results: [{ premium: 198 }] });
108	  });
109	
110	  // --- Quote: "alike" means exactly the same component type (❓) ---
111	  it("prices 2 runes + 1 moonstone at 75 G base premium (no block: different types)", () => {
112	    const result = runScenario({
