/**
 * A claim reimburses each damaged item, less the deductible, and draws the
 * total down from the policy's remaining cap.
 *
 * The cap binds the payout, not merely the report: a claim worth more than the
 * policy has left pays out only what remains. Clamping here — in subunits,
 * before `toPayoutGold` rounds — is what keeps the cap from running negative
 * and lets it reach exactly 0 rather than a rounded near-zero.
 */
const applyClaim = (step: ClaimStep, ledger: Ledger): StepOutcome => {
  const policy = assumePolicy(ledger, step.policy);
  const payout = Math.min(
    reimbursementForIncident(step.incident, policy),
    policy.remainingCap,
  );
  const remainingCap = policy.remainingCap - payout;

